                DataRow dr_documentType = SET_DocumentType.GetDataByKey(CompanyID, this.DocumentTypeID, PeriodID, null, sqltrans);

                foreach (Gate_OutwardDetail ACd in colAssetCostDetail)
                {
                    ACd.Gate_OutwardDetailID = Gate_OutwardDetail.GetNewGate_OutwardDetailID(f_CompanyID, f_PeriodID, sqltrans);
                    ACd.Insert(sqltrans);
                }

                //sth.Insert(sqltrans);

                //foreach (INV_StockTransactionDetail std in colSTDet)
                //{
                //    std.TransactionDetailID = STDetailID++;
                //    std.SourceLineID = int.Parse((SourceLineID++).ToString());
                //    std.Insert(sqltrans);
                //}

                #region Insert In SET_DocumentApprove When StatusCode = "ReleaseForApprove"

                if (this.StatusCode.Equals(Convert.ToInt16(Enumaration.CurrentStatus.ReleaseForApprove)))
                {
                    objDocumentApprove.DocumentApproveID = SET_DocumentApprove.GetNewDocumentApproveID(this.f_CompanyID, this.f_PeriodID, sqltrans);
                    objDocumentApprove.Insert(sqltrans);
                }

                #endregion

                if (IsGRN)
                {
                    if (th != null && this.StatusCode.Equals(Convert.ToInt16(Enumaration.CurrentStatus.Approved)) && dr_documentType != null
                        && dr_documentType["TransactionType"] != null && dr_documentType["TransactionType"] != DBNull.Value
                        && !dr_documentType["TransactionType"].ToString().Equals("No Impact"))
                    {

                        #region For Stock Transaction Header & Detail

                        sth.DocumentNo = int.Parse(f_DocumentNo.ToString());
                        sth.StockTransactionID = INV_StockTransactionHeader.GetNewStockTransactionID(f_CompanyID, f_PeriodID, sqltrans);
                        sth.Insert(sqltrans);

                        long transactionDetailID = INV_StockTransactionDetail.GetNewTransactionDetailID(f_CompanyID, f_PeriodID, sqltrans);

                        foreach (INV_StockTransactionDetail std in colSTDetail)
                        {
                            std.SourceCode = f_DocumentNo.ToString();
                            std.SourceHeaderID = int.Parse(f_Gate_OutwardHeaderID.ToString());
                            std.SourceLineID = int.Parse((SourceLineID++).ToString());
                            std.SourceDocumentTypeID = f_DocumentTypeID;
                            std.StockTransactionID = sth.StockTransactionID;
                            std.TransactionDetailID = transactionDetailID++;
                            std.Insert(sqltrans);
                        }

                        #endregion

                        #region Insert In GL_TransactionHeader

                        th.DocumentNo = f_DocumentNo;
                        th.TransactionID = GL_TransactionHeader.GetNewTransactionID(f_CompanyID, f_PeriodID, sqltrans);
                        th.Insert(sqltrans);

                        #endregion

                        #region Insert In GL_TransactionDetail

                        foreach (GL_TransactionDetail td in colTranDetail)
                        {
                            td.TransactionID = th.TransactionID;
                            td.SourceHeaderID = int.Parse(this.Gate_OutwardHeaderID.ToString());
                            td.Insert(sqltrans);
                        }

                        #endregion
                    }


                }
                else {
                    if (this.StatusCode.Equals(Convert.ToInt16(Enumaration.CurrentStatus.Approved)))
                    {

                        #region For Stock Transaction Header & Detail

                        sth.DocumentNo = int.Parse(f_DocumentNo.ToString());
                        sth.StockTransactionID = INV_StockTransactionHeader.GetNewStockTransactionID(f_CompanyID, f_PeriodID, sqltrans);
                        sth.Insert(sqltrans);

                        long transactionDetailID = INV_StockTransactionDetail.GetNewTransactionDetailID(f_CompanyID, f_PeriodID, sqltrans);

                        foreach (INV_StockTransactionDetail std in colSTDetail)
                        {
                            std.SourceCode = f_DocumentNo.ToString();
                            std.SourceHeaderID = int.Parse(f_Gate_OutwardHeaderID.ToString());
                            std.SourceLineID = int.Parse((SourceLineID++).ToString());
                            std.SourceDocumentTypeID = f_DocumentTypeID;
                            std.StockTransactionID = sth.StockTransactionID;
                            std.TransactionDetailID = transactionDetailID++;
                            std.Insert(sqltrans);
                        }

                        #endregion

                        #region Insert In GL_TransactionHeader

                        th.DocumentNo = f_DocumentNo;
                        th.TransactionID = GL_TransactionHeader.GetNewTransactionID(f_CompanyID, f_PeriodID, sqltrans);
                        th.Insert(sqltrans);

                        #endregion

                        #region Insert In GL_TransactionDetail

                        foreach (GL_TransactionDetail td in colTranDetail)
                        {
                            td.TransactionID = th.TransactionID;
                            td.SourceHeaderID = int.Parse(this.Gate_OutwardHeaderID.ToString());
                            td.Insert(sqltrans);
                        }

                        #endregion
                    }
                    if (this.StatusCode.Equals(Convert.ToInt16(Enumaration.CurrentStatus.InProcess)))
                    {

                        #region For Stock Transaction Header & Detail

                        sth.DocumentNo = int.Parse(f_DocumentNo.ToString());
                        sth.StockTransactionID = INV_StockTransactionHeader.GetNewStockTransactionID(f_CompanyID, f_PeriodID, sqltrans);
                        sth.InsertInProStatus(sqltrans);

                        long transactionDetailID = INV_StockTransactionDetail.GetNewTransactionDetailID(f_CompanyID, f_PeriodID, sqltrans);

                        foreach (INV_StockTransactionDetail std in colSTDetail)
                        {
                            std.SourceCode = f_DocumentNo.ToString();
                            std.SourceHeaderID = int.Parse(f_Gate_OutwardHeaderID.ToString());
                            std.SourceLineID = int.Parse((SourceLineID++).ToString());
                            std.SourceDocumentTypeID = f_DocumentTypeID;
                            std.StockTransactionID = sth.StockTransactionID;
                            std.TransactionDetailID = transactionDetailID++;
                            std.Insert(sqltrans);
                        }

                        #endregion

                        #region Insert In GL_TransactionHeader

                        th.DocumentNo = f_DocumentNo;
                        th.TransactionID = GL_TransactionHeader.GetNewTransactionID(f_CompanyID, f_PeriodID, sqltrans);
                        th.Insert(sqltrans);

                        #endregion

                        #region Insert In GL_TransactionDetail

                        foreach (GL_TransactionDetail td in colTranDetail)
                        {
                            td.TransactionID = th.TransactionID;
                            td.SourceHeaderID = int.Parse(this.Gate_OutwardHeaderID.ToString());
                            td.Insert(sqltrans);
                        }

                        #endregion
                    }
                }



                result = true;
            }
            catch (BusinessLogicException ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            finally
            {
                if (result)
                    SqlHelper.CommitTransaction(sqltrans);
                else
                    SqlHelper.RollBackTransaction(sqltrans, "InsertGate");
            }

            return result;
        }

