        public static DataTable GetAllDataFiscal(string strWhere, ref int ReturnTotalRows, string OrderBy, int? PageIndex = null, int? PageSize = null,
        Enumaration.SortDirection sortdirection = Enumaration.SortDirection.asc, SqlTransaction objTransaction = null,int CurrentFiscalID=0)
        {
            List<SqlParameter> sqlparamsList = new List<SqlParameter>();
            OrderBy = (!string.IsNullOrEmpty(OrderBy) ? " Order By [" + OrderBy + "] " + sortdirection.ToString() : String.Empty);
            DataTable dt = null;

            sqlparamsList.Add(new SqlParameter("@CurrentFiscalID", CurrentFiscalID));



            try
            {
                if (PageIndex != null)
                {
                    sqlparamsList.Add(new SqlParameter("@PageIndex", PageIndex));
                    sqlparamsList.Add(new SqlParameter("@PageSize", PageSize));
                    sqlparamsList.Add(new SqlParameter("@TotalRows", ReturnTotalRows));

                    SqlParameter sqlparamTotalRows = sqlparamsList.Find(a => a.ParameterName == "@TotalRows");
                    sqlparamTotalRows.Direction = ParameterDirection.Output;

                    SqlParameter[] sqlparams = sqlparamsList.ToArray();

                    string Query_SelectAll_WithPaging = @" SELECT [CompanyID], [PeriodID], [Gate_OutwardHeaderID], [DocumentTypeID], [DocumentNo], [DocumentDate], [Comments], [CostCenterID], [LocationID], [StatusCode], [TotalAmount], [SupplierID], [SourceHeaderID], [Status], [CreatedBy], [CreateDate], [CreatedByValue], [UpdatedBy], [UpdateDate], [UpdatedByValue], [IncurredOnID], [VehicalNo], ROW_NUMBER() Over (Order by CompanyID, Gate_OutwardHeaderID, PeriodID) as 'Row' FROM [Gate_OutwardHeader] 
    inner join Set_PeriodCustom on  
 Gate_OutwardHeader.DocumentDate between Set_PeriodCustom.StartDate and Set_PeriodCustom.EndDate 
and Set_PeriodCustom.Status = 1 and SET_PeriodCustom.FiscalID = @CurrentFiscalID

                    "; 

                    if (objTransaction != null)
                        dt = SqlHelper.ExecuteDataset(objTransaction, CommandType.Text, string.Format(Paging, Query_SelectAll_WithPaging + strWhere + (!string.IsNullOrEmpty(OrderBy) ? OrderBy : string.Empty), Query_SelectAll_WithPaging + strWhere + (!string.IsNullOrEmpty(OrderBy) ? OrderBy : string.Empty)), sqlparams).Tables[0];
                    else
                        dt = SqlHelper.ExecuteDataset(CommandType.Text, string.Format(Paging, Query_SelectAll_WithPaging + strWhere + (!string.IsNullOrEmpty(OrderBy) ? OrderBy : string.Empty), Query_SelectAll_WithPaging + strWhere + (!string.IsNullOrEmpty(OrderBy) ? OrderBy : string.Empty)), sqlparams).Tables[0];

                    ReturnTotalRows = int.Parse(sqlparamTotalRows.Value.ToString());
                }
                else
                {

                    string Query_SelectAll_WithoutPaging = @" SELECT [CompanyID], [PeriodID], [Gate_OutwardHeaderID], [DocumentTypeID], [DocumentNo], [DocumentDate], [Comments], [CostCenterID], [LocationID], [StatusCode], [TotalAmount], [SupplierID], [SourceHeaderID], [Status], [CreatedBy], [CreateDate], [CreatedByValue], [UpdatedBy], [UpdateDate], [UpdatedByValue], [IncurredOnID], [VehicalNo] FROM [Gate_OutwardHeader] 

inner join Set_PeriodCustom on  
 Gate_OutwardHeader.DocumentDate between Set_PeriodCustom.StartDate and Set_PeriodCustom.EndDate 
and Set_PeriodCustom.Status = 1 and SET_PeriodCustom.FiscalID = @CurrentFiscalID

"; 


                    if (objTransaction != null)
                        dt = SqlHelper.ExecuteDataset(objTransaction, CommandType.Text, Query_SelectAll_WithoutPaging + strWhere + (!string.IsNullOrEmpty(OrderBy) ? OrderBy : string.Empty), sqlparamsList.ToArray()).Tables[0];
                    else
                        dt = SqlHelper.ExecuteDataset(CommandType.Text, Query_SelectAll_WithoutPaging + strWhere + (!string.IsNullOrEmpty(OrderBy) ? OrderBy : string.Empty), sqlparamsList.ToArray()).Tables[0];
                }
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }

            return dt;
        }

        public bool UpdateACHeaderAndDetail(INV_StockTransactionHeader sth, List<Gate_OutwardDetail> colAddAssetCostDetail,
            List<Gate_OutwardDetail> colUpdateAssetCostDetail, List<Gate_OutwardDetail> colDeleteAssetCostDetail, List<INV_StockTransactionDetail> colAddSTDetail, List<INV_StockTransactionDetail> colUpdateSTDetail, List<INV_StockTransactionDetail> colDeleteSTDetail, SET_DocumentApprove objDocumentApprove)
        {   
            bool result = false;
            SqlTransaction sqltrans = SqlHelper.GetTransaction("UpdateGate");

            try
            {
                this.UpdateDataByKey(sqltrans);
                //sth.UpdateDataByKeyOwn(sqltrans);
                sth.UpdateDataByKey(sqltrans);

                long SoruceLineID = Gate_OutwardDetail.GetNewGate_OutwardDetailID(f_CompanyID, f_PeriodID, sqltrans);

                foreach (Gate_OutwardDetail ACdAdd in colAddAssetCostDetail)
                {
                    ACdAdd.Gate_OutwardDetailID = Gate_OutwardDetail.GetNewGate_OutwardDetailID(f_CompanyID, f_PeriodID, sqltrans); 
                    ACdAdd.Insert(sqltrans);
                }

                foreach (Gate_OutwardDetail ACdUpdate in colUpdateAssetCostDetail)
                    ACdUpdate.UpdateDetailDataByKey(sqltrans);

                foreach (Gate_OutwardDetail ACdDelete in colDeleteAssetCostDetail)
                {
                    Gate_OutwardDetail.DeleteDataByKey(sqltrans, f_UpdatedBy.Value, f_UpdateDate.Value, f_UpdatedByValue, f_CompanyID, ACdDelete.Gate_OutwardDetailID, f_PeriodID);
                }

                foreach (INV_StockTransactionDetail stdAdd in colAddSTDetail)
                {
                    stdAdd.TransactionDetailID = INV_StockTransactionDetail.GetNewTransactionDetailID(sqltrans);
                    stdAdd.SourceLineID = int.Parse((SoruceLineID++).ToString());
                    stdAdd.Insert(sqltrans);
                }

                foreach (INV_StockTransactionDetail stdUpdate in colUpdateSTDetail)
                    stdUpdate.UpdateDataByKey(sqltrans);

                foreach (INV_StockTransactionDetail ddDelete in colDeleteSTDetail)
                {
                    INV_StockTransactionDetail.DeleteDataByKey(sqltrans, f_UpdatedBy.Value, f_UpdateDate.Value, f_UpdatedByValue, ddDelete.TransactionDetailID, f_CompanyID, f_PeriodID);
                }

                #region Insert In SET_DocumentApprove When StatusCode = "ReleaseForApprove"

                if (this.StatusCode.Equals(Convert.ToInt16(Enumaration.CurrentStatus.ReleaseForApprove)))
                {
                    objDocumentApprove.DocumentApproveID = SET_DocumentApprove.GetNewDocumentApproveID(this.f_CompanyID, this.f_PeriodID, sqltrans);
                    objDocumentApprove.Insert(sqltrans);
                }

                #endregion

                result = true;
            }
            catch (BusinessLogicException ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            finally
            {
                if (result)
                    SqlHelper.CommitTransaction(sqltrans);
                else
                    SqlHelper.RollBackTransaction(sqltrans, "UpdateGate");
            }

            return result;
        }

        public bool DeleteACHeaderAndDetail(List<Gate_OutwardDetail> colDeleteAssetCostDetail, List<INV_StockTransactionDetail> colDeleteSTDetail)
        {
            bool result = false;
            SqlTransaction sqltrans = SqlHelper.GetTransaction("DeleteGate");

            try
            {

                DeleteDataByKey(sqltrans, f_UpdatedBy.Value, f_UpdateDate.Value, UpdatedByValue, f_CompanyID, f_Gate_OutwardHeaderID, f_PeriodID);

                foreach (Gate_OutwardDetail ACddDelete in colDeleteAssetCostDetail)
                    Gate_OutwardDetail.DeleteDataByKey(sqltrans, f_UpdatedBy.Value, f_UpdateDate.Value, f_UpdatedByValue, f_CompanyID, ACddDelete.Gate_OutwardDetailID, f_PeriodID);

                foreach (INV_StockTransactionDetail STddDelete in colDeleteSTDetail)
                    INV_StockTransactionDetail.DeleteDataByKey(sqltrans, f_UpdatedBy.Value, f_UpdateDate.Value, f_UpdatedByValue, STddDelete.TransactionDetailID);

                result = true;
            }
            catch (BusinessLogicException ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }
            finally
            {
                if (result)
                    SqlHelper.CommitTransaction(sqltrans);
                else
                    SqlHelper.RollBackTransaction(sqltrans, "DeleteGate");
            }
            return result;
        }

