        public static DataTable GetDataForGONNO(int companyID, int periodID , int CustomerID = 0)
        {
            DataTable dtToReturn = null;

            try
            {
                StringBuilder sb = new StringBuilder();
                
                SqlParameter[] sqlparams = new SqlParameter[3];
                sqlparams[0] = new SqlParameter("@CompanyID", companyID);
                sqlparams[1] = new SqlParameter("@PeriodID", periodID);

                #region Query

                const string Query_GetDataforGONNO = @"Select distinct Cast(Gate_OutwardHeader.Gate_OutwardHeaderID as varchar(10)) as  Gate_OutwardHeaderID
,Cast(Gate_OutwardHeader.DocumentNo as varchar(50)) as GONNO 
, Cast(SET_DocumentType.DocumentType as Varchar(150)) as  DocumentType
 from Gate_OutwardHeader
Left Join SET_DocumentType on SET_DocumentType.DocumentTypeID =  Gate_OutwardHeader.DocumentTypeID
Inner Join Gate_OutwardDetail  on Gate_OutwardDetail.Gate_OutwardHeaderID = Gate_OutwardHeader.Gate_OutwardHeaderID

 Where Gate_OutwardHeader.DOCUMENTTypeID = (Select SET_DocumentType.DocumentTypeID from SET_DocumentType Where DocumentType = 'OpenReturnableGON')

 And Gate_OutwardHeader.Status =1 

 And Gate_OutwardHeader.CompanyID = @CompanyID
 And Gate_OutwardHeader.PeriodID = @PeriodID
{0}
";

                #endregion

               
                    sb.Append(" And Gate_OutwardHeader.SupplierID = " + CustomerID);
           
                DataSet ds = SqlHelper.ExecuteDataset(CommandType.Text, string.Format(Query_GetDataforGONNO,sb), sqlparams);

                if (ds != null && ds.Tables.Count > 0)
                    dtToReturn = ds.Tables[0];
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }

            return dtToReturn;
        }

