        public static DataTable GetDataForItemIssuanceGatePassReport(int companyID, int periodID, int categoryID, string itemID, Nullable<DateTime> fromDate = null, Nullable<DateTime> toDate = null,
         SqlConnection objConnection = null, SqlTransaction objTransaction = null)
        {
            DataTable dr = null;

       

            try
            {
                StringBuilder sb = new StringBuilder();
                SqlParameter[] sqlparams = new SqlParameter[4];
                sqlparams[0] = new SqlParameter("@CompanyID", companyID);
                sqlparams[1] = new SqlParameter("@PeriodID", periodID);
                sqlparams[2] = new SqlParameter("@FromDate", fromDate);
                sqlparams[3] = new SqlParameter("@ToDate", toDate);


                DataSet ds = null;
                if (fromDate != null && toDate != null)
                {
                    sb.Append(" and convert(date,DocumentDate) between @FromDate AND @ToDate ");
                }
                else if (fromDate != null && toDate == null)
                {
                    sb.Append(" and convert(date,DocumentDate) = @FromDate ");
                }
                else if (fromDate == null && toDate != null)
                {
                    sb.Append(" and convert(date,DocumentDate) = @ToDate");
                }

                if (categoryID > 0)
                    sb.Append(" AND INV_ITEm.ItemTypeID = " + categoryID);

                if (!string.IsNullOrEmpty(itemID))
                {
                    sb.Append(" and INV_ITEm.ItemID = " + int.Parse(itemID.ToString()));
                }

                if (objTransaction != null)
                    ds = SqlHelper.ExecuteDataset(objTransaction, CommandType.Text, string.Format(FnI.QueryResourceLibrary.Inventory.Transaction.Gate_OutwardHeader.Query_GetDataForItemIssuanceGatePassReport, sb), sqlparams);
                else if (objConnection != null)
                    ds = SqlHelper.ExecuteDataset(objConnection, CommandType.Text, string.Format(FnI.QueryResourceLibrary.Inventory.Transaction.Gate_OutwardHeader.Query_GetDataForItemIssuanceGatePassReport, sb), sqlparams);
                else
                    ds = SqlHelper.ExecuteDataset(CommandType.Text, string.Format(FnI.QueryResourceLibrary.Inventory.Transaction.Gate_OutwardHeader.Query_GetDataForItemIssuanceGatePassReport, sb), sqlparams);

                if (ds != null && ds.Tables.Count > 0 && ds.Tables[0].Rows.Count > 0)
                    dr = ds.Tables[0];
            }
            catch (Exception ex)
            {
                SqlHelper.LogException(ex);
                throw ex;
            }

            return dr;
        }

